-- 悦途旅行预订平台 数据库初始化脚本（由 tools/gen-sql.js 自动生成，请勿手改数据部分）
-- 执行方式: mysql -u root -p < init.sql
CREATE DATABASE IF NOT EXISTS ctrip_travel CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ctrip_travel;

DROP TABLE IF EXISTS hotel, attraction, train_ticket, flight, bus_ticket, travel_order, order_change;

CREATE TABLE hotel (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  city VARCHAR(32) NOT NULL, name VARCHAR(128) NOT NULL,
  stars INT NOT NULL, score VARCHAR(8), distance VARCHAR(16), area VARCHAR(64),
  tags JSON, base_price INT NOT NULL, rooms JSON,
  KEY idx_hotel_city (city)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE attraction (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  city VARCHAR(32) NOT NULL, name VARCHAR(128) NOT NULL,
  level VARCHAR(16), score VARCHAR(8), open_time VARCHAR(32), area VARCHAR(64),
  tags JSON, base_price INT NOT NULL, ticket_types JSON,
  KEY idx_attr_city (city)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE train_ticket (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  from_city VARCHAR(32) NOT NULL, to_city VARCHAR(32) NOT NULL,
  train_no VARCHAR(16) NOT NULL, type_code CHAR(1) NOT NULL, type_name VARCHAR(8),
  from_station VARCHAR(32), to_station VARCHAR(32),
  dep_time VARCHAR(8), arr_time VARCHAR(16), duration VARCHAR(16), seats JSON,
  KEY idx_train_route (from_city, to_city)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE flight (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  from_city VARCHAR(32) NOT NULL, to_city VARCHAR(32) NOT NULL,
  flight_no VARCHAR(16) NOT NULL, airline VARCHAR(32), plane VARCHAR(16),
  from_airport VARCHAR(32), to_airport VARCHAR(32),
  dep_time VARCHAR(8), arr_time VARCHAR(16), duration VARCHAR(16), cabins JSON,
  KEY idx_flight_route (from_city, to_city)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE bus_ticket (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  from_city VARCHAR(32) NOT NULL, to_city VARCHAR(32) NOT NULL,
  dep_time VARCHAR(8), from_station VARCHAR(48), to_station VARCHAR(48),
  duration VARCHAR(16), bus_type VARCHAR(16), price INT NOT NULL, seats INT NOT NULL,
  KEY idx_bus_route (from_city, to_city)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE travel_order (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  order_no VARCHAR(32) NOT NULL UNIQUE,
  idem_key VARCHAR(64),                 -- 客户端幂等键：同一人重复提交只入库一次（唯一约束见下方 uk_order_idem）
  type VARCHAR(16) NOT NULL, item_id BIGINT,
  user_id BIGINT,
  title VARCHAR(256), date_text VARCHAR(128), choice_text VARCHAR(64),
  quantity INT NOT NULL, unit_price DECIMAL(10,2), total_price DECIMAL(10,2),
  contact_name VARCHAR(32), phone VARCHAR(16),
  status VARCHAR(16) DEFAULT '待支付',  -- 待支付 / 已支付 / 已取消 / 已退款
  pay_time DATETIME, cancel_time DATETIME, refund_time DATETIME,
  pay_deadline DATETIME,               -- 待支付订单的支付截止；超时由 OrderExpiryTask 自动取消并回补库存
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  -- 定时任务每分钟按 (status, pay_deadline) 扫超时未支付订单，没这个索引就是全表扫
  KEY idx_order_status_deadline (status, pay_deadline),
  KEY idx_order_type (type),
  KEY idx_order_user (user_id),
  -- 幂等键按「人」唯一，而不是全局唯一：前端订单号是 C+毫秒时间戳，
  -- 两个人同一毫秒下单并不冲突，全局唯一会把第二个人的正常订单误判成重复提交
  UNIQUE KEY uk_order_idem (idem_key, user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 改签记录：一笔订单改签几次就几行，seq 从 1 递增（OrderService.changeOrder 写入）
CREATE TABLE order_change (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  order_no VARCHAR(32) NOT NULL,
  seq INT NOT NULL,
  old_item_id BIGINT, new_item_id BIGINT,
  old_title VARCHAR(256), new_title VARCHAR(256),
  old_date_text VARCHAR(128), new_date_text VARCHAR(128),
  old_choice VARCHAR(64), new_choice VARCHAR(64),
  old_unit_price DECIMAL(10,2), old_total_price DECIMAL(10,2),
  new_unit_price DECIMAL(10,2), new_total_price DECIMAL(10,2),
  fee DECIMAL(10,2) NOT NULL DEFAULT 0,
  diff DECIMAL(10,2) NOT NULL DEFAULT 0,   -- 正数补差价 / 负数退差额
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_change_order (order_no),
  UNIQUE KEY uk_change_seq (order_no, seq)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

