-- 汽车票无预置数据，由后端按客运定价规律（0.3元/公里、均速80km/h）首次搜索时生成入库

-- 2026-10-25 新增：用户表（登录注册）
-- 2026-10-28 变更：口令注册通道下线后，username 一律由服务端按「m+手机号 / e+邮箱前缀」自动生成，
-- 用户真正记住的凭据是手机号或邮箱，所以 email 也带唯一索引（NULL 不参与唯一约束，
-- 早期只有手机号的账号留空即可）。
CREATE TABLE IF NOT EXISTS app_user (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  username VARCHAR(50) NOT NULL UNIQUE,
  pwd_hash VARCHAR(128) NOT NULL,
  salt VARCHAR(64) NOT NULL,
  nickname VARCHAR(50),
  phone VARCHAR(20),
  email VARCHAR(128) UNIQUE,
  auth_ver INT NOT NULL DEFAULT 0,   -- 凭证版本号：改密码即 +1，旧令牌随之全部失效
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2026-10-28 新增：登录会话表（此前会话只存内存，重启即全员掉线、也无法多实例共享）
CREATE TABLE IF NOT EXISTS user_session (
  token CHAR(32) PRIMARY KEY,
  user_id BIGINT NOT NULL,
  auth_ver INT NOT NULL DEFAULT 0,   -- 签发时的凭证版本，与 app_user.auth_ver 不一致即视为失效
  expire_time DATETIME NOT NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_session_user (user_id),
  KEY idx_session_expire (expire_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2026-10-28 新增：登录短信验证码。演示站没有短信网关，码由服务端随机生成；
-- 表里只存 PBKDF2 哈希，明文码要么回显给页面（开发开关），要么只写日志。
-- 一次性使用：used=1 之后即使还在有效期内也不能再登。
CREATE TABLE IF NOT EXISTS sms_code (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  phone VARCHAR(16) NOT NULL,
  scene VARCHAR(16) NOT NULL DEFAULT 'login',   -- 预留：login / register / bind 等
  code_hash VARCHAR(128) NOT NULL,              -- pbkdf2$迭代数$盐$哈希
  attempts INT NOT NULL DEFAULT 0,              -- 已校验失败次数，超过上限直接作废
  used TINYINT NOT NULL DEFAULT 0,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  expire_time DATETIME NOT NULL,
  KEY idx_sms_phone (phone, scene, used, expire_time),
  KEY idx_sms_expire (expire_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2026-10-28 新增：扫码登录场景。手机确认页与电脑轮询读写同一行，
-- 因此不能用内存 Map（重启会丢正在扫码的场景）。
-- 这里不存任何令牌：会话是电脑来领取的那一刻才由 user_session 现签的（见 QrLoginService.poll），
-- 数据库里不留「躺着等人来取」的凭据；领取成功后整行删除。
CREATE TABLE IF NOT EXISTS login_qrcode (
  scene CHAR(32) PRIMARY KEY,
  status VARCHAR(16) NOT NULL DEFAULT 'PENDING',  -- PENDING/SCANNED/CONFIRMED/REJECTED/EXPIRED/CLAIMED
  user_id BIGINT NULL,                            -- 扫码并确认的账号
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  scan_time DATETIME NULL,
  confirm_time DATETIME NULL,
  expire_time DATETIME NOT NULL,
  KEY idx_qr_expire (expire_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2026-10-28 新增：邮箱验证码。与 sms_code 同构（只存 PBKDF2 哈希、一次性、失败次数达上限即作废），
-- 单开一张表而不是给 sms_code 加通用 target 列：列名 phone 的语义、限流维度与规则都不同，
-- 混用会让「按号码合算的跨场景配额」变成「按一个含糊的 target 字符串合算」。
CREATE TABLE IF NOT EXISTS email_code (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(128) NOT NULL,
  scene VARCHAR(16) NOT NULL DEFAULT 'register',   -- register / login
  code_hash VARCHAR(128) NOT NULL,                 -- pbkdf2$迭代数$盐$哈希
  attempts INT NOT NULL DEFAULT 0,                 -- 已校验失败次数，超过上限直接作废
  used TINYINT NOT NULL DEFAULT 0,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  expire_time DATETIME NOT NULL,
  KEY idx_email_code_target (email, scene, used, expire_time),
  KEY idx_email_code_expire (expire_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2026-10-28 新增：第三方授权场景（微信/QQ/微博一类「用第三方账号登录」的路）。
-- 与 login_qrcode 一样必须落库：授权页与发起页是两次互不相干的请求。
-- 这里存的是第三方「声称」的账号身份（open_id/昵称/头像），不存任何令牌；
-- 会话是发起方轮询领取那一刻现签的，领取成功后整行删除，与扫码同一口径。
CREATE TABLE IF NOT EXISTS oauth_scene (
  state CHAR(32) PRIMARY KEY,
  provider VARCHAR(16) NOT NULL,                   -- wechat / qq / weibo
  status VARCHAR(16) NOT NULL DEFAULT 'PENDING',   -- PENDING/APPROVED/REJECTED/EXPIRED/CLAIMED
  open_id VARCHAR(64) NULL,                        -- 授权通过后第三方给的账号标识
  nickname VARCHAR(64) NULL,
  avatar VARCHAR(8) NULL,                          -- 头像取色（演示站没有真实头像 URL）
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  approve_time DATETIME NULL,
  expire_time DATETIME NOT NULL,
  KEY idx_oauth_expire (expire_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2026-10-28 新增：第三方账号与本站账号的绑定关系。
-- UNIQUE(provider, open_id) 是「同一个人第二次授权落到同一个账号」的唯一依据，
-- 也是第三方注册唯一性的真正兜底（先查后插只负责给清楚的提示）。
CREATE TABLE IF NOT EXISTS user_oauth (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  provider VARCHAR(16) NOT NULL,
  open_id VARCHAR(64) NOT NULL,
  user_id BIGINT NOT NULL,
  nickname VARCHAR(64) NULL,                       -- 授权时第三方给的昵称，仅作展示与比对
  avatar VARCHAR(8) NULL,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  last_login_time DATETIME NULL,
  UNIQUE KEY uk_oauth_identity (provider, open_id),
  KEY idx_oauth_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2026-10-25 新增：拓展模块表（旅游/用车/礼品卡/全球购/企业商旅），种子数据见 tools/seed-modules.js
CREATE TABLE IF NOT EXISTS vacation_product (id BIGINT AUTO_INCREMENT PRIMARY KEY, city VARCHAR(30) NOT NULL, name VARCHAR(120) NOT NULL, days INT NOT NULL, style VARCHAR(30), score VARCHAR(10), tags JSON, price INT NOT NULL, packages JSON) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS car_product (id BIGINT AUTO_INCREMENT PRIMARY KEY, city VARCHAR(30) NOT NULL, brand VARCHAR(60) NOT NULL, level VARCHAR(30), price INT NOT NULL, deposit INT NOT NULL, stock INT NOT NULL, feature VARCHAR(120)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS gift_card (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, face_value INT NOT NULL, sell_price INT NOT NULL, stock INT NOT NULL, intro VARCHAR(200)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS global_shop (id BIGINT AUTO_INCREMENT PRIMARY KEY, category VARCHAR(30) NOT NULL, name VARCHAR(120) NOT NULL, brand VARCHAR(60), price INT NOT NULL, origin VARCHAR(40), stock INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS biz_travel_apply (id BIGINT AUTO_INCREMENT PRIMARY KEY, company VARCHAR(100) NOT NULL, credit_code VARCHAR(32) NOT NULL, contact VARCHAR(50), phone VARCHAR(20), status VARCHAR(20) DEFAULT '审核中', create_time DATETIME DEFAULT CURRENT_TIMESTAMP, KEY idx_company (company)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2026-10-25 新增：船票表（客运班轮），种子数据见 tools/seed-ships.js
CREATE TABLE IF NOT EXISTS ship_ticket (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  from_city VARCHAR(32) NOT NULL, to_city VARCHAR(32) NOT NULL,
  dep_time VARCHAR(8), from_port VARCHAR(48), to_port VARCHAR(48),
  duration VARCHAR(16), ship_name VARCHAR(40), seat_type VARCHAR(20), price INT NOT NULL, seats INT NOT NULL,
  KEY idx_ship_route (from_city, to_city)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2026-11-22 新增：悦途金融（拿去花授信分期 / 信用微贷 / 出行保障 / 钱包账单）
-- 与 sql/migration-2026-11-22-finance.sql 同构，存量库执行迁移脚本即可
CREATE TABLE IF NOT EXISTS fin_account (
  user_id BIGINT PRIMARY KEY,
  real_name VARCHAR(32), id_card VARCHAR(18),
  income INT DEFAULT 0, job VARCHAR(32),
  credit_status VARCHAR(16) NOT NULL DEFAULT 'none',
  credit_limit DECIMAL(12,2) NOT NULL DEFAULT 0,
  credit_used DECIMAL(12,2) NOT NULL DEFAULT 0,
  credit_score INT NOT NULL DEFAULT 0,
  wallet DECIMAL(12,2) NOT NULL DEFAULT 0,
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fin_loan (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  user_id BIGINT NOT NULL,
  loan_no VARCHAR(32) NOT NULL UNIQUE,
  kind VARCHAR(16) NOT NULL,
  order_no VARCHAR(32), title VARCHAR(128),
  principal DECIMAL(12,2) NOT NULL,
  months INT NOT NULL, rate DECIMAL(5,2) NOT NULL,
  monthly DECIMAL(12,2) NOT NULL,
  paid_months INT NOT NULL DEFAULT 0,
  status VARCHAR(16) NOT NULL DEFAULT '还款中',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_loan_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fin_repay (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  loan_id BIGINT NOT NULL, seq INT NOT NULL,
  due_date DATE NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  principal DECIMAL(12,2) NOT NULL,
  interest DECIMAL(12,2) NOT NULL,
  status VARCHAR(16) NOT NULL DEFAULT '待还',
  paid_time DATETIME,
  KEY idx_repay_loan (loan_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fin_policy (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  user_id BIGINT NOT NULL,
  policy_no VARCHAR(32) NOT NULL UNIQUE,
  plan VARCHAR(16) NOT NULL, plan_name VARCHAR(32) NOT NULL,
  price DECIMAL(12,2) NOT NULL,
  insured VARCHAR(32) NOT NULL, destination VARCHAR(32) NOT NULL,
  start_date DATE NOT NULL, end_date DATE NOT NULL,
  status VARCHAR(16) NOT NULL DEFAULT '保障中',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_policy_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fin_claim (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  policy_id BIGINT NOT NULL, user_id BIGINT NOT NULL,
  claim_no VARCHAR(32) NOT NULL UNIQUE,
  type VARCHAR(16) NOT NULL,
  amount DECIMAL(12,2) NOT NULL, payout DECIMAL(12,2) NOT NULL,
  reason VARCHAR(255),
  status VARCHAR(16) NOT NULL DEFAULT '审核中',
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  review_time DATETIME,
  KEY idx_claim_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fin_tx (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  user_id BIGINT NOT NULL,
  kind VARCHAR(16) NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  balance_after DECIMAL(12,2) NOT NULL,
  memo VARCHAR(128), ref_no VARCHAR(32),
  create_time DATETIME DEFAULT CURRENT_TIMESTAMP,
  KEY idx_tx_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
